referenceSolutions.javascript:
function frequencyFilesPeakTicket(readings) {
  const a=readings; let out=[];
  const counts=new Map();for(const x of a)counts.set(x,(counts.get(x)||0)+1);for(const x of [...counts.keys()].sort((x,y)=>x-y))out.push(counts.get(x));
  let answer=out.length?out[0]:0;for(const x of out)if(x>answer)answer=x;return answer;
}

